#!/usr/bin/env bash
# parity_bench.sh — per-call Snowflake fallback for Phase 4 (parity) +
# Phase 5 (benchmark). Session variables don't survive across sessions
# in per-call clients, so the run id is generated by the shell and
# interpolated into literal table names, which the caller then uses
# across subsequent per-call invocations.
#
# Lifecycle:
#   1. Caller runs `parity_bench.sh materialise <orig> <opt>` — writes
#      the parity scratch tables and prints their names to stdout for
#      the caller to use.
#   2. Caller runs parity + benchmark queries against those names (any
#      number of invocations).
#   3. Caller runs `parity_bench.sh cleanup <orig_name> <opt_name>`
#      (or Ctrl-C the caller script, which is wrapped in a trap by
#      the SKILL.md recipe to call `cleanup`).
#
# This split exists because `trap cleanup EXIT` on the materialise
# script would drop the tables immediately when the script exited —
# before the caller could run anything against them. Cleanup lives in
# a separate command that the caller invokes explicitly.
#
# Usage:
#   parity_bench.sh materialise <orig_sql_file> <opt_sql_file>
#   parity_bench.sh cleanup     <orig_table_fqn> <opt_table_fqn>
#
# Env for materialise:
#   SNOWFLAKE_RUN_SQL    command that runs stdin as Snowflake SQL
#                        (e.g. 'snowsql -c myconn')
#   SQO_DEV_SCHEMA       REQUIRED — user own dev schema (never shared).
#
# Env for cleanup: SNOWFLAKE_RUN_SQL only.

set -eu

: "${SNOWFLAKE_RUN_SQL:?SNOWFLAKE_RUN_SQL command required, e.g. snowsql -c myconn}"

cmd="${1:?materialise | cleanup required}"
shift

case "$cmd" in
  materialise)
    ORIG_SQL="${1:?original SQL file required}"
    OPT_SQL="${2:?optimised SQL file required}"
    : "${SQO_DEV_SCHEMA:?SQO_DEV_SCHEMA required — use the caller own dev schema, never a shared one}"

    # Shell-generated RUN_ID → interpolated into literal table names →
    # always available for cleanup. Old 'SET parity_orig = ...' approach
    # ran in session 1 and the DROP in session 2 and failed with
    # "session variable does not exist".
    RUN_ID="$(uuidgen 2>/dev/null | tr -d - | tr '[:lower:]' '[:upper:]' || date +%s%N)"
    ORIG_TABLE="${SQO_DEV_SCHEMA}._SQO_ORIG_${RUN_ID}"
    OPT_TABLE="${SQO_DEV_SCHEMA}._SQO_OPT_${RUN_ID}"

    # Materialise each side once, with cache off. Any failure here
    # cleans up partials via the on-error trap, then re-exits.
    on_error() {
      printf 'DROP TABLE IF EXISTS %s;\nDROP TABLE IF EXISTS %s;\n' \
        "$ORIG_TABLE" "$OPT_TABLE" | $SNOWFLAKE_RUN_SQL >/dev/null 2>&1 || true
    }
    trap on_error ERR INT TERM

    {
      printf 'ALTER SESSION SET USE_CACHED_RESULT = FALSE;\n'
      printf 'CREATE OR REPLACE TRANSIENT TABLE %s AS\n' "$ORIG_TABLE"
      cat "$ORIG_SQL"
      printf '\n;\n'
      printf 'CREATE OR REPLACE TRANSIENT TABLE %s AS\n' "$OPT_TABLE"
      cat "$OPT_SQL"
      printf '\n;\n'
    } | $SNOWFLAKE_RUN_SQL

    # On success: do NOT trap EXIT. The tables must survive this
    # script exit so the caller can query them. Print the names on
    # stdout, caller captures them for later `cleanup` call.
    trap - ERR INT TERM
    printf 'ORIG_TABLE=%s\nOPT_TABLE=%s\n' "$ORIG_TABLE" "$OPT_TABLE"
    cat >&2 <<EOF
parity_bench.sh: scratch tables materialised. When done, run:
  parity_bench.sh cleanup "$ORIG_TABLE" "$OPT_TABLE"
EOF
    ;;

  cleanup)
    ORIG_TABLE="${1:?original table FQN required}"
    OPT_TABLE="${2:?optimised table FQN required}"
    printf 'DROP TABLE IF EXISTS %s;\nDROP TABLE IF EXISTS %s;\n' \
      "$ORIG_TABLE" "$OPT_TABLE" | $SNOWFLAKE_RUN_SQL
    echo "parity_bench.sh: cleanup OK — dropped $ORIG_TABLE and $OPT_TABLE" >&2
    ;;

  *)
    echo "parity_bench.sh: usage: parity_bench.sh {materialise <orig.sql> <opt.sql> | cleanup <orig_fqn> <opt_fqn>}" >&2
    exit 1
    ;;
esac
